public int fill(FluidStack resource, IFluidHandler.FluidAction action) {
    if (resource.isEmpty() || !this.isFluidValid(resource)) {
        return 0;
    }
    int filled = Math.min(resource.getAmount(), this.capacity - this.getFillAmount());
    if (action.simulate()) {
        return filled;
